class EmployeeProfile { String empId, empName; double salary; boolean isIntern; EmployeeProfile(String id, String name, double pay) { empId=id; empName=name; salary=pay; isIntern=false; } EmployeeProfile(String id, String name) { this(id, name, 0); isIntern=true; } void printProfile() { System.out.println(empId + " | " + empName + " | Rs " + salary + " | Intern: " + isIntern); } }
public class EmployeeConstructorDemo { public static void main(String[] args) { new EmployeeProfile("E-101", "Divya", 65000).printProfile(); new EmployeeProfile("E-102", "Arjun").printProfile(); } }
